import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { useSocket } from '../hooks/useSocket';

function ProviderDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [services, setServices] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [earnings, setEarnings] = useState({ totalRevenue: 0, totalEarnings: 0, platformFees: 0, totalBookings: 0 });
  const [pendingPayout, setPendingPayout] = useState(0);
  const [payoutHistory, setPayoutHistory] = useState([]);
  const [pendingPayoutAmount, setPendingPayoutAmount] = useState(0);
  const [pendingPayoutCount, setPendingPayoutCount] = useState(0);
  const [recentPayments, setRecentPayments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingPayouts, setLoadingPayouts] = useState(false);
  const [showPayoutModal, setShowPayoutModal] = useState(false);
  const [showServiceModal, setShowServiceModal] = useState(false);
  const [editingService, setEditingService] = useState(null);
  const [payoutAmount, setPayoutAmount] = useState('');
  const [showEditProfileModal, setShowEditProfileModal] = useState(false);
  const [showBankModal, setShowBankModal] = useState(false);
  const [hasBankAccount, setHasBankAccount] = useState(false);
  const [loadingBank, setLoadingBank] = useState(false);
  const [loadingStripe, setLoadingStripe] = useState(false);
  const [stripeStatus, setStripeStatus] = useState({ hasAccount: false, status: null, onboardingComplete: false });

  // WebSocket states
  const [notifications, setNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifications, setShowNotifications] = useState(false);
  const [newBookingAlert, setNewBookingAlert] = useState(null);

  const [bankAccount, setBankAccount] = useState({
    accountName: '',
    accountNumber: '',
    bankName: '',
    routingNumber: ''
  });

  const [settings, setSettings] = useState({
    emailNotifications: true,
    pushNotifications: true,
    smsNotifications: false,
    autoConfirm: false,
    priceAlerts: true,
    calendarSync: false,
    language: 'english'
  });

  const [businessProfile, setBusinessProfile] = useState({
    businessName: user?.businessName || '',
    ownerName: `${user?.firstName || ''} ${user?.lastName || ''}`,
    email: user?.email || '',
    phone: user?.phone || '',
    address: user?.businessAddress || '',
    taxId: user?.businessLicense || '',
    logo: user?.profilePicture || `https://ui-avatars.com/api/?background=10b981&color=fff&name=${user?.businessName?.charAt(0) || 'P'}`
  });

  const [editProfileData, setEditProfileData] = useState({
    businessName: businessProfile.businessName,
    ownerName: businessProfile.ownerName,
    email: businessProfile.email,
    phone: businessProfile.phone,
    address: businessProfile.address,
    taxId: businessProfile.taxId
  });

  const [serviceForm, setServiceForm] = useState({
    name: '', description: '', category: 'oil-change', price: '', duration: '30',
    discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: ''
  });

  const categories = [
    { id: 'oil-change', name: 'Oil Change', icon: '🛢️' },
    { id: 'brake-repair', name: 'Brake Repair', icon: '🛑' },
    { id: 'tire-service', name: 'Tire Service', icon: '🛞' },
    { id: 'engine-repair', name: 'Engine Repair', icon: '🔧' },
    { id: 'ac-repair', name: 'AC Repair', icon: '❄️' },
    { id: 'transmission', name: 'Transmission', icon: '⚙️' },
    { id: 'detailing', name: 'Detailing', icon: '🧼' },
    { id: 'maintenance', name: 'Maintenance', icon: '📋' },
    { id: 'electrical', name: 'Electrical', icon: '⚡' },
    { id: 'body-repair', name: 'Body Repair', icon: '🚘' }
  ];

  const token = localStorage.getItem('token');

  // ============ WEBSOCKET INTEGRATION ============
  const { 
    isConnected,
    updateBookingStatus,
    onBookingStatusChanged,
    onNewNotification,
    joinBookingRoom,
    sendChatMessage,
    onNewMessage
  } = useSocket();

  // Listen for booking status changes
  useEffect(() => {
    const unsubscribe = onBookingStatusChanged((data) => {
      console.log('📅 Booking status changed:', data);
      fetchBookings();
      fetchEarnings();

      if (data.status === 'confirmed') {
        toast.success(`Booking ${data.bookingId} confirmed!`);
      } else if (data.status === 'cancelled') {
        toast.warning(`Booking ${data.bookingId} was cancelled`);
      } else if (data.status === 'completed') {
        toast.success(`Booking ${data.bookingId} completed!`);
      }
    });
    return () => unsubscribe && unsubscribe();
  }, [onBookingStatusChanged]);

  // Listen for new notifications (including new bookings)
  useEffect(() => {
    const unsubscribe = onNewNotification((notification) => {
      console.log('🔔 New notification:', notification);
      setNotifications(prev => [notification, ...prev]);
      setUnreadCount(prev => prev + 1);

      // Special handling for new bookings
      if (notification.type === 'new_booking') {
        setNewBookingAlert(notification);
        toast.info(`🔔 NEW BOOKING: ${notification.data?.serviceName || 'New service booked'}!`, {
          onClick: () => setActiveTab('bookings'),
          autoClose: 10000
        });
      } else {
        toast.info(notification.message);
      }
    });
    return () => unsubscribe && unsubscribe();
  }, [onNewNotification]);

  // Join booking rooms for active bookings
  useEffect(() => {
    bookings.forEach(booking => {
      if (booking.status === 'pending' || booking.status === 'confirmed' || booking.status === 'in-progress') {
        joinBookingRoom(booking._id);
      }
    });
  }, [bookings, joinBookingRoom]);

  // Update booking status with WebSocket
  const handleUpdateBookingStatus = async (bookingId, status) => {
    try {
      // Use WebSocket for real-time update
      updateBookingStatus(bookingId, status);

      // Also update via API for persistence
      const res = await fetch(`http://localhost:5000/api/services/provider/bookings/${bookingId}/status`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ status })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Booking ${status}!`);
        fetchBookings();
        fetchEarnings();
      } else {
        toast.error(data.error || 'Failed to update booking');
      }
    } catch (error) {
      toast.error('Failed to update booking');
    }
  };

  // Download invoice
  const downloadInvoice = async (paymentId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/invoices/download/${paymentId}`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      if (res.ok) {
        const blob = await res.blob();
        const url = window.URL.createObjectURL(blob);
        window.open(url, '_blank');
        setTimeout(() => window.URL.revokeObjectURL(url), 100);
        toast.success('Invoice opened in new tab');
      } else {
        toast.error('Failed to download invoice');
      }
    } catch (err) {
      toast.error('Error downloading invoice');
    }
  };

  // Fetch all data
  useEffect(() => {
    fetchAllData();
    fetchBankAccount();
    checkStripeStatus();
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      await Promise.all([
        fetchServices(),
        fetchBookings(),
        fetchEarnings(),
        fetchPayoutHistory()
      ]);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const fetchServices = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/services/provider/my-services', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) setServices(data.services || []);
    } catch (error) {
      console.error(error);
      setServices([]);
    }
  };

  const fetchBookings = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/services/provider/bookings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) setBookings(data.bookings || []);
    } catch (error) {
      console.error(error);
      setBookings([]);
    }
  };

  const fetchEarnings = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/payments/provider/earnings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        setEarnings(data.earnings || { totalRevenue: 0, totalEarnings: 0, platformFees: 0, totalBookings: 0 });
        setPendingPayout(data.pendingPayout || 0);
        setRecentPayments(data.recentPayments || []);
      }
    } catch (error) {
      console.error(error);
    }
  };

  const fetchPayoutHistory = async () => {
    setLoadingPayouts(true);
    try {
      const res = await fetch('http://localhost:5000/api/payments/provider/payout-history', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        setPayoutHistory(data.payoutHistory || []);
        setPendingPayoutAmount(data.pendingAmount || 0);
        setPendingPayoutCount(data.pendingCount || 0);
      }
    } catch (error) {
      console.error('Error fetching payout history:', error);
    } finally {
      setLoadingPayouts(false);
    }
  };

  const fetchBankAccount = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/provider/bank-account', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success && data.bankAccount) {
        setBankAccount(data.bankAccount);
        setHasBankAccount(true);
      }
    } catch (error) {
      console.error('Error fetching bank account:', error);
    }
  };

  const saveBankAccount = async (e) => {
    e.preventDefault();
    setLoadingBank(true);
    try {
      const res = await fetch('http://localhost:5000/api/provider/bank-account', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify(bankAccount)
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Bank account saved!');
        setHasBankAccount(true);
        setShowBankModal(false);
      } else {
        toast.error(data.error || 'Failed to save bank account');
      }
    } catch (error) {
      toast.error('Failed to save bank account');
    } finally {
      setLoadingBank(false);
    }
  };

  const deleteBankAccount = async () => {
    if (window.confirm('Remove bank account?')) {
      try {
        const res = await fetch('http://localhost:5000/api/provider/bank-account', {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Bank account removed');
          setHasBankAccount(false);
          setBankAccount({ accountName: '', accountNumber: '', bankName: '', routingNumber: '' });
        }
      } catch (error) {
        toast.error('Failed to remove');
      }
    }
  };

  const checkStripeStatus = async () => {
    try {
      const res = await fetch('http://localhost:5000/api/stripe/account-status', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      setStripeStatus(data);
    } catch (error) {
      console.error('Error checking Stripe status:', error);
    }
  };

  const connectStripe = async () => {
    setLoadingStripe(true);
    try {
      const res = await fetch('http://localhost:5000/api/stripe/onboarding-link', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success && data.url) {
        window.location.href = data.url;
      } else {
        toast.error('Failed to create Stripe link');
      }
    } catch (error) {
      toast.error('Failed to connect Stripe');
    } finally {
      setLoadingStripe(false);
    }
  };

  const disconnectStripe = async () => {
    if (window.confirm('Disconnect Stripe?')) {
      try {
        const res = await fetch('http://localhost:5000/api/stripe/disconnect', {
          method: 'POST',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Stripe disconnected');
          checkStripeStatus();
        }
      } catch (error) {
        toast.error('Failed to disconnect');
      }
    }
  };

  const updateProfile = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:5000/api/provider/business-profile', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({
          businessName: editProfileData.businessName,
          businessAddress: editProfileData.address,
          businessLicense: editProfileData.taxId,
          phone: editProfileData.phone
        })
      });
      const data = await res.json();
      if (data.success) {
        toast.success('Profile updated!');
        setBusinessProfile({
          ...businessProfile,
          businessName: editProfileData.businessName,
          address: editProfileData.address,
          taxId: editProfileData.taxId,
          phone: editProfileData.phone
        });
        setShowEditProfileModal(false);
      } else {
        toast.error(data.error || 'Failed to update');
      }
    } catch (error) {
      toast.error('Failed to update profile');
    }
  };

  const handleServiceSubmit = async (e) => {
    e.preventDefault();
    try {
      const payload = {
        ...serviceForm,
        price: parseFloat(serviceForm.price),
        duration: parseInt(serviceForm.duration),
        discountedPrice: serviceForm.discountedPrice ? parseFloat(serviceForm.discountedPrice) : undefined,
        tags: serviceForm.tags.split(',').map(t => t.trim()),
        requirements: serviceForm.requirements.split(',').map(r => r.trim()),
        inclusions: serviceForm.inclusions.split(',').map(i => i.trim())
      };

      let url = 'http://localhost:5000/api/services';
      let method = 'POST';

      if (editingService) {
        url = `http://localhost:5000/api/services/${editingService._id}`;
        method = 'PUT';
      }

      const res = await fetch(url, {
        method,
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify(payload)
      });
      const data = await res.json();
      if (data.success) {
        toast.success(editingService ? 'Service updated!' : 'Service added!');
        setShowServiceModal(false);
        setEditingService(null);
        setServiceForm({ name: '', description: '', category: 'oil-change', price: '', duration: '30', discountedPrice: '', warranty: '', tags: '', requirements: '', inclusions: '' });
        fetchServices();
      } else {
        toast.error(data.error || 'Failed to save');
      }
    } catch (error) {
      toast.error('Failed to save service');
    }
  };

  const handleDeleteService = async (serviceId) => {
    if (window.confirm('Delete this service?')) {
      try {
        const res = await fetch(`http://localhost:5000/api/services/${serviceId}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success('Service deleted!');
          fetchServices();
        }
      } catch (error) {
        toast.error('Failed to delete');
      }
    }
  };

  const handleToggleStatus = async (serviceId) => {
    try {
      const res = await fetch(`http://localhost:5000/api/services/${serviceId}/toggle-status`, {
        method: 'PATCH',
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Service ${data.service.isActive ? 'activated' : 'deactivated'}`);
        fetchServices();
      }
    } catch (error) {
      toast.error('Failed to update status');
    }
  };

  const editService = (service) => {
    setEditingService(service);
    setServiceForm({
      name: service.name,
